import time

LIMIT = 100           # requests per minute
request_counts = {}   # "user_id:window" -> count

def is_allowed(user_id):
    window = int(time.time()) // 60
    key = f"{user_id}:{window}"

    count = request_counts.get(key, 0)
    if count >= LIMIT:
        return False

    request_counts[key] = count + 1
    return True

@app.before_request
